"""Records the small, role-specific Runtime 0.4 point report."""

from __future__ import annotations

import json
import pathlib
import unicodedata

from pi_harness.locking import state_lock
from pi_harness.runtime_v2 import (
    AgentReport,
    HardStop,
    PointIdentity,
    PointRole,
    PointScope,
    ReportOutcome,
    RuntimeState,
    _save_runtime_state_unlocked,
    load_runtime_state,
)


def read_report(
    report_path: pathlib.Path | None,
    report_text: str | None,
) -> tuple[str, HardStop | None]:
    if report_path is not None and report_text is not None:
        raise ValueError("Choose either a report file or report text.")
    if report_path is None and report_text is None:
        raise ValueError("Reports require a report file, stdin report, or summary.")
    raw = report_path.read_text(encoding="utf-8") if report_path is not None else report_text
    try:
        payload = json.loads(raw)
    except (TypeError, json.JSONDecodeError) as error:
        raise ValueError("Runtime v4 reports must be valid JSON.") from error
    if not isinstance(payload, dict):
        raise ValueError("Runtime v4 reports must be a JSON object.")
    expected = {"summary", "hard_stop"}
    if set(payload) != expected:
        unknown = sorted(set(payload) - expected)
        missing = sorted(expected - set(payload))
        details = []
        if unknown:
            details.append("unknown " + ", ".join(unknown))
        if missing:
            details.append("missing " + ", ".join(missing))
        raise ValueError("Runtime v4 report fields are invalid: " + "; ".join(details) + ".")
    summary = payload["summary"]
    if not isinstance(summary, str) or not summary:
        raise ValueError("Report summary must be a non-empty string.")
    return sanitise_text(summary), _parse_hard_stop(payload["hard_stop"])


def read_feedback(feedback_path: pathlib.Path | None, feedback_text: str | None) -> str | None:
    """Retains the narrow text helper for callers that only need sanitisation."""
    if feedback_path is not None and feedback_text is not None:
        raise ValueError("Choose either a feedback file or feedback text.")
    if feedback_path is not None:
        feedback_text = feedback_path.read_text(encoding="utf-8")
    return None if feedback_text is None else sanitise_text(feedback_text)


def record_report(
    state_path: pathlib.Path,
    plan_path: pathlib.Path,
    report: AgentReport,
) -> RuntimeState:
    _validate_report_shape(report)
    with state_lock(state_path):
        state = load_runtime_state(state_path)
        if state is None:
            raise ValueError(f"Runtime v4 state does not exist: {state_path}.")
        if _canonical_path(state.plan_path) != _canonical_path(str(plan_path)):
            raise ValueError("Report plan does not match the state plan.")
        if state.active_point is None or not _points_match(state.active_point, report.point):
            raise ValueError("Report point does not match the active point.")
        if state.active_invocation is not None and report.invocation_id != state.active_invocation.invocation_id:
            raise ValueError("Report invocation does not match the active invocation.")
        if state.active_invocation is None and report.invocation_id is not None:
            raise ValueError("Report has no active invocation to match.")
        if any(existing.report_id == report.report_id for existing in state.reports):
            raise ValueError(f"Report id already exists: {report.report_id}.")
        state.reports.append(
            report._replace(
                point=state.active_point,
                summary=sanitise_text(report.summary),
                hard_stop=(
                    None
                    if report.hard_stop is None
                    else HardStop(
                        sanitise_text(report.hard_stop.reason),
                        sanitise_text(report.hard_stop.evidence),
                    )
                ),
            )
        )
        _save_runtime_state_unlocked(state_path, state)
        return state


def sanitise_text(value: str) -> str:
    if not isinstance(value, str):
        raise ValueError("Report text must be a string.")
    return "".join(
        character
        if character in "\n\r\t" or unicodedata.category(character) != "Cc"
        else f"\\u{ord(character):04x}"
        for character in value
    )


def _validate_report_shape(report: AgentReport) -> None:
    if not isinstance(report, AgentReport):
        raise ValueError("Report must use the Runtime v4 report type.")
    if not isinstance(report.point, PointIdentity):
        raise ValueError("Report point must use the Runtime v4 point type.")
    if report.role not in set(PointRole) or report.role != report.point.role:
        raise ValueError("Report role does not match its point role.")
    if report.outcome != ReportOutcome.COMPLETE:
        raise ValueError("Runtime v4 reports only support point completion.")
    if not isinstance(report.report_id, str) or not report.report_id:
        raise ValueError("Report id must be a non-empty string.")
    if not isinstance(report.summary, str) or not report.summary:
        raise ValueError("Report summary must be a non-empty string.")
    if not isinstance(report.reported_at, str) or not report.reported_at:
        raise ValueError("Report time must be a non-empty string.")
    if report.invocation_id is not None and (not isinstance(report.invocation_id, str) or not report.invocation_id):
        raise ValueError("Report invocation id must be a non-empty string or null.")
    if report.hard_stop is not None and (
        not isinstance(report.hard_stop, HardStop)
        or not report.hard_stop.reason
        or not report.hard_stop.evidence
    ):
        raise ValueError("Hard-stop fields must be non-empty strings.")
    if report.point.scope == PointScope.STEP:
        if report.point.step_number is None or report.point.pass_number is None:
            raise ValueError("Step reports require step and pass identity.")
    else:
        if report.point.cleanup_generation is None or report.point.cleanup_pass_number is None:
            raise ValueError("Cleanup reports require cleanup identity.")


def _parse_hard_stop(value: object) -> HardStop | None:
    if value is None:
        return None
    if not isinstance(value, dict) or set(value) != {"reason", "evidence"}:
        raise ValueError("Hard stop fields must be exactly reason and evidence.")
    reason = value["reason"]
    evidence = value["evidence"]
    if not isinstance(reason, str) or not reason or not isinstance(evidence, str) or not evidence:
        raise ValueError("Hard-stop reason and evidence must be non-empty strings.")
    return HardStop(sanitise_text(reason), sanitise_text(evidence))


def _canonical_path(path_name: str) -> pathlib.Path:
    return pathlib.Path(path_name).expanduser().resolve()


def _points_match(left: PointIdentity, right: PointIdentity) -> bool:
    return (
        _canonical_path(left.plan_path) == _canonical_path(right.plan_path)
        and left.step_number == right.step_number
        and left.pass_number == right.pass_number
        and left.role == right.role
        and left.unit_id == right.unit_id
        and left.scope == right.scope
        and left.budget_generation == right.budget_generation
        and left.cleanup_generation == right.cleanup_generation
        and left.cleanup_pass_number == right.cleanup_pass_number
    )
